// === Tab: mySketch ===
let canvasSize = 1024;
let gridSize = 24;
let cellSize = canvasSize / gridSize;
let colors = [];

function setup() {
  createCanvas(canvasSize, canvasSize);
  strokeWeight(3);
  noFill();

  // Generate 4 random clear colors with opacity between 50% and 80%
  let color1 = color('rgba(175, 215, 237, ' + random(0.5, 0.8) + ')'); // Light blue
  let color2 = color('rgba(255, 182, 193, ' + random(0.5, 0.8) + ')'); // Light pink
  let color3 = color('rgba(255, 255, 153, ' + random(0.5, 0.8) + ')'); // Light yellow
  let color4 = color('rgba(200, 200, 200, ' + random(0.5, 0.8) + ')'); // Light gray
  colors = shuffle([color1, color2, color3, color4]);
}

function draw() {
  background(0);

  // Change the sine frequency to 0.01 to make the waves more gentle
  let freq = 0.01; 

  for (let x = 0; x < gridSize; x++) {
    for (let y = 0; y < gridSize; y++) {
      let centerX = x * cellSize + cellSize / 2;
      let centerY = y * cellSize + cellSize / 2;
      let hexagonSize = cellSize * (0.2 + 2 * sin(frameCount * freq + x + y));
      let colorIndex = x * gridSize + y; // Use the index of the hexagon to select its color
      stroke(colors[colorIndex % 4]); // Select the color based on the modulo operation
      drawHexagon(centerX, centerY, hexagonSize);
    }
  }
}

function drawHexagon(x, y, size) {
  let radius = size / (1 + sin(TWO_PI / 12));
  beginShape();
  for (let i = 0; i < 6; i++) {
    let angle = TWO_PI * i / 6 - HALF_PI;
    let px = x + radius * cos(angle);
    let py = y + radius * sin(angle);
    vertex(px, py);
  }
  endShape(CLOSE);
}

